   528  /* Copy any children of Node sourceNodeId to another node destinationNodeId. */
   529  static UA_StatusCode
   530  copyChildNodes(UA_Server *server, UA_Session *session,
   531                 const UA_NodeId *sourceNodeId, const UA_NodeId *destinationNodeId) {
   532      /* Browse to get all children of the source */
   533      UA_BrowseDescription bd;
   534      UA_BrowseDescription_init(&bd);
   535      bd.nodeId = *sourceNodeId;
   536      bd.referenceTypeId = UA_NODEID_NUMERIC(0, UA_NS0ID_AGGREGATES);
   537      bd.includeSubtypes = true;
   538      bd.browseDirection = UA_BROWSEDIRECTION_FORWARD;
   539      bd.nodeClassMask = UA_NODECLASS_OBJECT | UA_NODECLASS_VARIABLE | UA_NODECLASS_METHOD;
   540      bd.resultMask = UA_BROWSERESULTMASK_REFERENCETYPEID | UA_BROWSERESULTMASK_NODECLASS |
   541          UA_BROWSERESULTMASK_BROWSENAME;
   542
   543      UA_BrowseResult br;
   544      UA_BrowseResult_init(&br);
   545      UA_UInt32 maxrefs = 0;
   546      Operation_Browse(server, session, &maxrefs, &bd, &br);
   547      if(br.statusCode != UA_STATUSCODE_GOOD)
   548          return br.statusCode;
   549
   550      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   551      for(size_t i = 0; i < br.referencesSize; ++i) {
   552          UA_ReferenceDescription *rd = &br.references[i];
   553          retval |= copyChildNode(server, session, destinationNodeId, rd);
   554      }
   555
   556      UA_BrowseResult_deleteMembers(&br);
   557      return retval;
   558  }
