   560  static UA_StatusCode
   561  addChildren(UA_Server *server, UA_Session *session,
   562              const UA_Node *node, const UA_Node *type) {
   563      /* Get the hierarchy of the type and all its supertypes */
   564      UA_NodeId *hierarchy = NULL;
   565      size_t hierarchySize = 0;
   566      UA_StatusCode retval = getTypeHierarchy(&server->config.nodestore, &type->nodeId,
   567                                              &hierarchy, &hierarchySize);
   568      if(retval != UA_STATUSCODE_GOOD)
   569          return retval;
   570
   571      /* Copy members of the type and supertypes (and instantiate them) */
   572      for(size_t i = 0; i < hierarchySize; ++i)
   573          retval |= copyChildNodes(server, session, &hierarchy[i], &node->nodeId);
   574      UA_Array_delete(hierarchy, hierarchySize, &UA_TYPES[UA_TYPES_NODEID]);
   575      return retval;
   576  }
