   578  /* Calls the global destructor internally of the global constructor succeeds and
   579   * the type-level constructor fails. */
   580  static UA_StatusCode callConstructors(UA_Server *server, UA_Session *session,
   581                                        const UA_Node *node, const UA_Node *type) {
   582      /* Get the node type constructor */
   583      const UA_NodeTypeLifecycle *lifecycle = NULL;
   584      if(node->nodeClass == UA_NODECLASS_OBJECT) {
   585          const UA_ObjectTypeNode *ot = (const UA_ObjectTypeNode*)type;
   586          lifecycle = &ot->lifecycle;
   587      } else if(node->nodeClass == UA_NODECLASS_VARIABLE) {
   588          const UA_VariableTypeNode *vt = (const UA_VariableTypeNode*)type;
   589          lifecycle = &vt->lifecycle;
   590      }
   591
   592      /* Call the global constructor */
   593      void *context = node->context;
   594      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   595      if(server->config.nodeLifecycle.constructor)
   596          retval = server->config.nodeLifecycle.constructor(server, &session->sessionId,
   597                                                            session->sessionHandle,
   598                                                            &node->nodeId, &context);
   599
   600      /* Call the type constructor */
   601      if(retval == UA_STATUSCODE_GOOD && lifecycle && lifecycle->constructor)
   602          retval = lifecycle->constructor(server, &session->sessionId,
   603                                          session->sessionHandle, &type->nodeId,
   604                                          type->context, &node->nodeId, &context);
   605
   606      /* Set the context *and* mark the node as constructed */
   607      if(retval == UA_STATUSCODE_GOOD)
   608          retval = UA_Server_editNode(server, &adminSession, &node->nodeId,
   609                                      (UA_EditNodeCallback)editNodeContext,
   610                                      context);
   611
   612      /* Fail. Call the global destructor. */
   613      if(retval != UA_STATUSCODE_GOOD && server->config.nodeLifecycle.destructor)
   614          server->config.nodeLifecycle.destructor(server, &session->sessionId,
   615                                                  session->sessionHandle,
   616                                                  &node->nodeId, context);
   617
   618      return retval;
   619  }
